style.css:
@-moz-document domain("discord.com"), domain("canary.discord.com"), domain("ptb.discord.com") {
:root { --hk-green: #00ff41; --hk-cyan: #00e5ff; --hk-bg: #050510; --hk-surface: #0a0a1a; --hk-text: #c8ffc8; --hk-font: "JetBrains Mono", monospace; }
  * { font-family: var(--hk-font) !important; }
  #app-mount { background: var(--hk-bg) !important; color: var(--hk-text) !important; }
  nav[class*="guilds"] { background: var(--hk-bg) !important; border-right: 1px solid rgba(0,255,65,0.2) !important; }
  nav[class*="sidebar"] { background: var(--hk-surface) !important; }
  [class*="username"] { color: var(--hk-cyan) !important; }
  [class*="messageContent"] { color: var(--hk-text) !important; }
  code, pre { background: #0f0f22 !important; color: var(--hk-green) !important; }
  a { color: var(--hk-cyan) !important; }
}
